import{_ as t,o as i,c as s,a6 as n}from"./chunks/framework.DhXJbKDf.js";const g=JSON.parse('{"title":"BC Government Design System WordPress Theme","description":"","frontmatter":{},"headers":[],"relativePath":"content/themes/design-system-wordpress-theme/overview.md","filePath":"content/themes/design-system-wordpress-theme/overview.md"}'),a={name:"content/themes/design-system-wordpress-theme/overview.md"};function r(o,e,l,h,m,d){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="bc-government-design-system-wordpress-theme" tabindex="-1">BC Government Design System WordPress Theme <a class="header-anchor" href="#bc-government-design-system-wordpress-theme" aria-label="Permalink to “BC Government Design System WordPress Theme”">​</a></h1><p>A WordPress theme built with the BC Government Design System, providing a comprehensive set of pre-built patterns and components for rapid site development.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The Design System WordPress Theme is a powerful tool that allows you to:</p><ul><li>Build complete websites using drag-and-drop patterns</li><li>Maintain BC Government design consistency</li><li>Leverage BC Government design tokens and styling</li><li>Create child themes that inherit all patterns and functionality</li></ul><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h2><p>This WordPress theme is specifically built for BC Government websites hosted on the Digital Engagement Solutions (GDX) platform. It implements the BC Government Design System to ensure consistent branding and user experience across government sites.</p><h2 id="how-to-activate-the-theme" tabindex="-1">How to Activate the Theme <a class="header-anchor" href="#how-to-activate-the-theme" aria-label="Permalink to “How to Activate the Theme”">​</a></h2><ol><li>Access your WordPress site&#39;s dashboard</li><li>Go to Appearance → Themes</li><li>Find &quot;Design System Theme&quot;</li><li>Click &quot;Activate&quot;</li></ol><p>::: note This theme is exclusively for use on BC Government WordPress sites hosted by GDX / Digital Engagement Solutions. :::</p><h3 id="using-the-theme" tabindex="-1">Using the Theme <a class="header-anchor" href="#using-the-theme" aria-label="Permalink to “Using the Theme”">​</a></h3><ol><li>Create a new page or post</li><li>Click the &quot;+&quot; button to add a block</li><li>Navigate to the &quot;Patterns&quot; tab</li><li>Browse available patterns under categories like: <ul><li>Banners</li><li>Cards</li><li>Text layouts</li><li>Contact sections</li><li>Team displays</li></ul></li></ol><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to “Key Features”">​</a></h3><ul><li><strong>Pre-built Patterns</strong>: Build pages by combining ready-made patterns</li><li><strong>BC Gov Design System Integration</strong>: Uses official BC Government design tokens</li><li><strong>Responsive Design</strong>: All patterns are mobile-friendly</li><li><strong>Accessibility</strong>: Built with WCAG compliance in mind</li><li><strong>Child Theme Support</strong>: Create custom themes while maintaining design system consistency</li></ul>',14)])])}const p=t(a,[["render",r]]);export{g as __pageData,p as default};
